/* example_usage.c */
#include "json_decoder.h"
#include "json_records.h"  // Generated by Python encoder

int main(void)
{
    json_decoder_t decoder;

    // Initialize decoder with generated arrays
    json_decoder_init(&decoder,
                     json_records,
                     JSON_RECORDS_COUNT,
                     string_table,
                     STRING_TABLE_SIZE,
                     record_controls,
                     RECORD_CONTROLS_COUNT);

    // Decode all objects
    json_decode_all_objects(&decoder);

    // Or decode specific objects
    printf("\n========================================\n");
    printf("Decoding specific objects:\n\n");
    
    for (uint32_t i = 0; i < decoder.num_controls; i++) {
        printf("Object %u (compact): ", i);
        uint32_t index = decoder.controls[i].start_position;
        json_decode_value_compact(&decoder, &index);
        printf("\n");
    }

    return 0;
}

